// An unknown key of an options object is a RangeError (src/internal/checkOptions.ts). The checks are generated by
// `node scripts/option-keys.mjs --write` from the option types: the first part checks that the sources are what the
// script writes (no function without its check), the second that representative functions of each area throw for an
// unknown key, also in a nested object, and accept the known keys.
import { spawnSync } from "node:child_process";
import { mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import {
  binomTest,
  cov,
  coxph,
  distSummary,
  factanal,
  glm,
  glmResiduals,
  integrate,
  lm,
  merge,
  onewayTest,
  optim,
  optimHess,
  outer,
  pivotLonger,
  pnorm,
  qgamma,
  quantile,
  rnorm,
  setSeed,
  splinefun,
  splinefunH,
  tabulate,
  tTest,
  wilcoxTest,
} from "../src/index.js";
import { lmer } from "../src/entries/mixed.js";

const root = fileURLToPath(new URL("..", import.meta.url));

/** The functions with a check of their own (R's messages; src/models/lmer.ts) */
const OWN_CHECK = new Set(["lmer", "lmerSummary", "lmerContest", "lmerAnova"]);

const unknown = (fn: string, key: string) => new RegExp(`^unknown option '${key.replace(/\./g, "\\.")}' for ${fn} \\(known: `);

describe("the generated checks of unknown keys", () => {
  const dir = mkdtempSync(join(tmpdir(), "option-keys-"));
  const tablePath = join(dir, "table.json");
  const run = spawnSync(process.execPath, ["scripts/option-keys.mjs", "--dry-run", "--table", tablePath], { cwd: root, encoding: "utf8" });
  const table = run.status === 0 ? (JSON.parse(readFileSync(tablePath, "utf8")) as { functions: { name: string; file: string }[] }) : undefined;
  rmSync(dir, { recursive: true, force: true });

  it("are what the script writes from the current option types", () => {
    expect(run.status, run.stderr).toBe(0);
    expect(run.stderr).toMatch(/ in 0 changed files/);
  });

  it("are in every exported function that takes an options object", () => {
    expect(table).toBeDefined();
    const functions = table!.functions;
    expect(functions.length).toBeGreaterThan(250);
    const sources = new Map<string, string>();
    const missing: string[] = [];
    for (const fn of functions) {
      if (OWN_CHECK.has(fn.name)) continue;
      const text = sources.get(fn.file) ?? readFileSync(join(root, fn.file), "utf8");
      sources.set(fn.file, text);
      if (!text.includes(`, "${fn.name}"); // generated: option-keys.mjs`)) missing.push(fn.name);
    }
    expect(missing).toEqual([]);
  });
});

describe("unknown keys of an options object", () => {
  it("are a RangeError naming the key, the function and the known keys (distributions, random numbers)", () => {
    expect(() => pnorm(1, { lowertail: false } as never)).toThrow(RangeError);
    expect(() => pnorm(1, { lowertail: false } as never)).toThrow(
      "unknown option 'lowertail' for pnorm (known: mean, sd, lowerTail, logP)",
    );
    expect(pnorm(1, { lowerTail: false })).toBe(pnorm(-1));
    expect(() => qgamma(0.5, 2, { rate: 1, scal: 2 } as never)).toThrow(unknown("qgamma", "scal"));
    expect(() => rnorm(2, { sd: 1, mu: 3 } as never)).toThrow(unknown("rnorm", "mu"));
    setSeed(1);
    expect(rnorm(2, { mean: 3 })).toHaveLength(2);
  });

  it("count also when the value is undefined", () => {
    expect(() => pnorm(1, { logp: undefined } as never)).toThrow(unknown("pnorm", "logp"));
  });

  it("are checked where the options can also be data (tests, descriptive statistics)", () => {
    const x = [1.2, 3.4, 2.2, 5.1, 4.4, 2.9];
    const y = [2.1, 4.4, 3.9, 6.2, 5.0, 3.3];
    expect(() => tTest(x, y, { conflevel: 0.9 } as never)).toThrow(unknown("tTest", "conflevel"));
    expect(() => tTest(x, { m: 1 } as never)).toThrow(unknown("tTest", "m"));
    expect(tTest(x, { mu: 1 }).nullValue).toBe(1);
    expect(tTest(x, y).pValue).toBeGreaterThan(0);
    // A data frame after a formula is data: its columns are not options
    const data = { v: [...x, ...y], grp: [...x.map(() => "a"), ...y.map(() => "b")] };
    expect(tTest("v ~ grp", data).pValue).toBe(tTest(x, y).pValue);
    expect(() => tTest("v ~ grp", data, { bogus: 1 } as never)).toThrow(unknown("tTest", "bogus"));
    expect(wilcoxTest("v ~ grp", data).pValue).toBe(wilcoxTest(x, y).pValue);
    expect(() => wilcoxTest(x, { exakt: false } as never)).toThrow(unknown("wilcoxTest", "exakt"));
    expect(onewayTest("v ~ grp", data).pValue).toBe(onewayTest([x, y]).pValue);
    expect(() => binomTest(3, 10, { prob: 0.3 } as never)).toThrow(unknown("binomTest", "prob"));
    expect(binomTest([3, 7], { p: 0.3 }).pValue).toBe(binomTest(3, 10, { p: 0.3 }).pValue);
    // cov(x, options) for a matrix, cov(x, y) for two samples
    expect(() => cov([[1, 2], [2, 3], [4, 1]], { methd: "spearman" } as never)).toThrow(unknown("cov", "methd"));
    expect(cov(x, y)).toBe(cov(x, y, { method: "pearson" }));
    expect(() => quantile(x, 0.5, { typ: 7 } as never)).toThrow(unknown("quantile", "typ"));
    expect(() => tabulate([1, 2, 2], { nbin: 3 } as never)).toThrow(unknown("tabulate", "nbin"));
    expect(tabulate([1, 2, 2], 3)).toEqual(tabulate([1, 2, 2], { nbins: 3 }));
    expect(() => outer([1, 2], [3], { fn: "+" } as never)).toThrow(unknown("outer", "fn"));
    expect(outer([1, 2], [3], "+")).toEqual(outer([1, 2], [3], { fun: "+" }));
  });

  it("are checked in nested objects with fixed keys (optim, glm, coxph, factanal)", () => {
    const f = (p: number[]) => (p[0]! - 1) ** 2 + (p[1]! + 2) ** 2;
    expect(() => optim([0, 0], f, { control: { maxitt: 10 } } as never)).toThrow(unknown("optim", "control.maxitt"));
    expect(() => optim([0, 0], f, { contrl: { maxit: 10 } } as never)).toThrow(unknown("optim", "contrl"));
    expect(optim([0, 0], f, { control: { maxit: 1000 } }).convergence).toBe(0);
    expect(() => optimHess([1, -2], f, undefined, { ndep: [1e-3, 1e-3] } as never)).toThrow(unknown("optimHess", "ndep"));

    const gx = [[1], [2], [3], [4], [5], [6]];
    const gy = [0, 0, 1, 0, 1, 1];
    expect(() => glm(gx, gy, { family: "binomial", weigths: [1, 1, 1, 1, 1, 1] } as never)).toThrow(unknown("glm", "weigths"));
    expect(() => glm(gx, [1, 2, 2, 3, 5, 6], { family: { family: "quasi", varianc: "mu" } } as never)).toThrow(
      unknown("glm", "family.varianc"),
    );
    expect(() => glm(gx, [1, 2, 2, 3, 5, 6], { family: "quasi", link: { pwr: 0.5 } } as never)).toThrow(unknown("glm", "link.pwr"));
    const fit = glm(gx, gy, { family: "binomial" });
    expect(glmResiduals(fit, "pearson")).toHaveLength(6);
    expect(() => glmResiduals(fit, { typ: "pearson" } as never)).toThrow(unknown("glmResiduals", "typ"));

    const time = [5, 8, 3, 9, 12, 4, 7, 10];
    const status = [1, 1, 0, 1, 0, 1, 1, 1];
    const cx = [[1], [0], [1], [0], [1], [0], [1], [0]];
    expect(() => coxph(time, status, cx, { control: { itermax: 5 } } as never)).toThrow(unknown("coxph", "control.itermax"));
    expect(() => coxph(time, status, cx, { control: { iterMax: 30 } })).not.toThrow();

    const covmat = [
      [1, 0.6, 0.5, 0.4],
      [0.6, 1, 0.45, 0.35],
      [0.5, 0.45, 1, 0.3],
      [0.4, 0.35, 0.3, 1],
    ];
    expect(() => factanal(null, 1, { covmat, nObs: 100, control: { lowr: 0.005 } } as never)).toThrow(unknown("factanal", "control.lowr"));
  });

  it("are checked in numerical methods, data handling and models", () => {
    expect(() => integrate(Math.exp, 0, 1, { reltol: 1e-10 } as never)).toThrow(unknown("integrate", "reltol"));
    expect(integrate(Math.exp, 0, 1, { relTol: 1e-10 }).value).toBeCloseTo(Math.E - 1, 12);
    const s = splinefun([1, 2, 3, 4], [1, 4, 9, 16]);
    expect(() => s([2.5], { derv: 1 } as never)).toThrow(unknown("the function from splinefun", "derv"));
    expect(s([2.5], 1)).toEqual(s([2.5], { deriv: 1 }));
    const h = splinefunH([1, 2, 3], [1, 4, 9], [2, 4, 6]);
    expect(() => h([2.5], { derivative: 1 } as never)).toThrow(unknown("the function from splinefunH", "derivative"));
    expect(() => merge({ k: [1, 2] }, { k: [2, 3] }, { bye: "k" } as never)).toThrow(unknown("merge", "bye"));
    expect(() => pivotLonger({ id: [1], a: [2] }, { cols: ["a"], namesto: "n" } as never)).toThrow(unknown("pivotLonger", "namesto"));
    const d = { y: [1.1, 2.3, 2.9, 4.2, 5.1, 5.8], x: [1, 2, 3, 4, 5, 6] };
    expect(() => lm("y ~ x", d, { wieghts: [1, 1, 1, 1, 1, 1] } as never)).toThrow(unknown("lm", "wieghts"));
    expect(() => distSummary("gamma", { shape: 2, rte: 1 })).toThrow(unknown("distSummary", "rte"));
    expect(distSummary("gamma", { shape: 2, rate: 2 }).mean).toBe(1);
    expect(distSummary("nbinom", { size: 3, mu: 2 }).mean).toBeCloseTo(2, 14);
  });

  it("keep lmer's own check (R's message, a TypeError)", () => {
    const d = { y: [1, 2, 3, 4, 5, 6, 7, 8], g: ["a", "a", "b", "b", "c", "c", "d", "d"] };
    expect(() => lmer("y ~ 1 + (1 | g)", d, { reml: false } as never)).toThrow(TypeError);
    expect(() => lmer("y ~ 1 + (1 | g)", d, { reml: false } as never)).toThrow("unused argument (reml)");
  });
});
